import matplotlib.pyplot as plt
import numpy as np
from types import SimpleNamespace

def solve(data):
     fig, ax = plt.subplots()
     state = {'point':None}
     def on_click(event):
         if event.inaxes is ax and event.xdata is not None and event.ydata is not None:
             state['point'] = [float(event.xdata),float(event.ydata)]
     cid = fig.canvas.mpl_connect('button_press_event',on_click)
     for e in data['events']:
         on_click(SimpleNamespace(inaxes=ax if e['inside'] else None,xdata=e['x'],ydata=e['y']))
     fig.canvas.mpl_disconnect(cid)
     plt.close(fig)
     return state['point']
